    public void VerifyClusterTransfersActionsForReview()
    {
        if(!designPreview||selectedCluster is not {} id)throw new InvalidOperationException("Use a cluster design review.");
        var state=clusterTransferStates[id];var first=this.GetVisualDescendants().OfType<ToggleButton>().First();first.IsChecked=false;if(state.Draft!.Uploads[0])throw new InvalidOperationException("Upload control did not update draft.");
        var selects=this.GetVisualDescendants().OfType<ComboBox>().ToArray();selects[1].SelectedIndex=2;if(state.Draft.Maps[0].Downloads[1]!=ClusterTransferOverride.Block)throw new InvalidOperationException("Download override did not update.");
        var revert=this.GetVisualDescendants().OfType<Button>().Single(b=>b.Content is Control c&&c.GetVisualDescendants().OfType<TextBlock>().Any(t=>t.Text=="Revert"));if(!revert.IsEnabled)throw new InvalidOperationException("Revert was not enabled.");revert.RaiseEvent(new Avalonia.Interactivity.RoutedEventArgs(Button.ClickEvent));Avalonia.Threading.Dispatcher.UIThread.RunJobs();UpdateLayout();
        if(!state.Draft.Uploads[0]||state.Draft.Maps[0].Downloads[1]!=ClusterTransferOverride.Inherit)throw new InvalidOperationException("Revert did not restore loaded transfer rules: "+JsonSerializer.Serialize(state.Draft)+" expected "+JsonSerializer.Serialize(state.Loaded!.Rules));
        state.Downloads=false;Render();Avalonia.Threading.Dispatcher.UIThread.RunJobs();UpdateLayout();var uploads=this.GetVisualDescendants().OfType<ComboBox>().ToArray();uploads[0].SelectedIndex=1;if(state.Draft.Maps[0].Uploads[0]!=ClusterTransferOverride.Allow)throw new InvalidOperationException("Uploads direction did not update its own override.");if(state.Draft.Maps[0].Downloads[0]!=ClusterTransferOverride.Inherit)throw new InvalidOperationException("Direction change altered download overrides.");state.Draft=ClusterTransferSettings.Clone(state.Loaded!.Rules);state.Downloads=true;Render();
    }
    private ToggleButton ClusterTransferToggle(bool value,Action<bool> change)
    {
        var toggle=new ToggleButton{IsChecked=value,Width=54,Height=30,HorizontalAlignment=HorizontalAlignment.Left};toggle.Template=new Avalonia.Controls.Templates.FuncControlTemplate<ToggleButton>((t,_)=>{var knob=new Border{Width=24,Height=24,CornerRadius=new(12),Background=Brushes.White,Margin=new(3),VerticalAlignment=VerticalAlignment.Center};var track=new Border{CornerRadius=new(15),Child=knob,BorderThickness=new(1),BorderBrush=Brush.Parse("#00DFFF")};void Paint(){track.Background=Brush.Parse(t.IsChecked==true?"#00BFD6":"#25455D");knob.HorizontalAlignment=t.IsChecked==true?HorizontalAlignment.Right:HorizontalAlignment.Left;}Paint();t.IsCheckedChanged+=(_,_)=>Paint();return track;});toggle.IsCheckedChanged+=(_,_)=>change(toggle.IsChecked==true);return toggle;
    }
    private async Task LoadClusterTransfersAsync(ClusterDefinition cluster,ApprovedClusterTransferState state)
    {
        if(state.Loading||state.Busy)return;state.Loading=true;try{state.Loaded=await client!.CallAsync<ClusterTransferReview>("cluster-transfers-read",cluster.Id,TimeSpan.FromSeconds(12),lifetime.Token);state.Draft=ClusterTransferSettings.Clone(state.Loaded.Rules);state.Notice="";}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Loading=false;if(managementTab==1&&selectedCluster==cluster.Id)Render();}
    }
    private async Task SaveClusterTransfersAsync(ClusterDefinition cluster,ApprovedClusterTransferState state)
    {
        if(state.Busy||state.Loaded is null||state.Draft is null)return;state.Busy=true;Render();try{var result=(await RunManagedScreenJobAsync(cluster.Id,"cluster-transfers-save-start",new ClusterTransferSave(state.Loaded,state.Draft))).Deserialize<ClusterTransferSaveResult>()??throw new InvalidDataException("Missing transfer save result.");state.Notice=result.Message;state.Loaded=await client!.CallAsync<ClusterTransferReview>("cluster-transfers-read",cluster.Id,TimeSpan.FromSeconds(12),lifetime.Token);state.Draft=ClusterTransferSettings.Clone(state.Loaded.Rules);}catch(Exception e)when(IsBasicSaveError(e)){state.Notice=e.Message;}finally{state.Busy=false;if(managementTab==1&&selectedCluster==cluster.Id)Render();}
    }
